import { prisma } from '@/lib/prisma';

async function resetUserAccount(userId: string) {
  const [deletedPosts, updatedUser] = await prisma.$transaction([
    prisma.post.deleteMany({ where: { authorId: userId } }),
    prisma.user.update({
      where: { id: userId },
      data: { status: 'RESET' }
    })
  ]);

  return { deletedPostsCount: deletedPosts.count, updatedUser };
}

import { prisma } from '@/lib/prisma';

export async function transferFunds(fromUserId: string, toUserId: string, amount: number) {
  return await prisma.$transaction(async (tx) => {
    // 1. Fetch sender balance with check
    const sender = await tx.account.findUniqueOrThrow({
      where: { userId: fromUserId }
    });

    if (sender.balance < amount) {
      throw new Error(`Insufficient funds: Balance is ${sender.balance}, requested ${amount}`);
    }

    // 2. Decrement sender balance
    const updatedSender = await tx.account.update({
      where: { userId: fromUserId },
      data: { balance: { decrement: amount } }
    });

    // 3. Increment receiver balance
    const updatedReceiver = await tx.account.update({
      where: { userId: toUserId },
      data: { balance: { increment: amount } }
    });

    // 4. Create ledger audit entry
    const auditLog = await tx.ledgerEntry.create({
      data: { fromUserId, toUserId, amount, status: 'COMPLETED' }
    });

    return { updatedSender, updatedReceiver, auditLog };
  }, {
    maxWait: 5000, // Maximum time to wait for a connection from the pool (5s)
    timeout: 10000 // Maximum time transaction can run before automatic rollback (10s)
  });
}
